#include "notify/proxy_preflight.hpp"
#include "notify/config.hpp"
#include <winsock2.h>
#include <ws2tcpip.h>
#include <windows.h>
#include <vector>
#include <stdexcept>
#include <chrono>
namespace notify {
WsaGuard::WsaGuard(){WSADATA d{};if(WSAStartup(MAKEWORD(2,2),&d)!=0)throw std::runtime_error("WSAStartup failed");owner_=true;}WsaGuard::~WsaGuard(){if(owner_)WSACleanup();}
static bool _recv_exact(SOCKET s,char*b,int n){int p=0;while(p<n){int r=recv(s,b+p,n-p,0);if(r<=0)return false;p+=r;}return true;}
static bool send_all(SOCKET s,const char*b,int n){int p=0;while(p<n){int r=send(s,b+p,n-p,0);if(r<=0)return false;p+=r;}return true;}
static SOCKET connect_tcp(const std::string&h,unsigned port,unsigned timeout){addrinfo hints{};hints.ai_socktype=SOCK_STREAM;hints.ai_family=AF_UNSPEC;addrinfo*res=nullptr;auto ps=std::to_string(port);if(getaddrinfo(h.c_str(),ps.c_str(),&hints,&res))return INVALID_SOCKET;SOCKET s=INVALID_SOCKET;for(auto*p=res;p;p=p->ai_next){s=socket(p->ai_family,p->ai_socktype,p->ai_protocol);if(s==INVALID_SOCKET)continue;u_long nb=1;ioctlsocket(s,FIONBIO,&nb);int rc=connect(s,p->ai_addr,(int)p->ai_addrlen);if(rc==SOCKET_ERROR&&WSAGetLastError()==WSAEWOULDBLOCK){fd_set w;FD_ZERO(&w);FD_SET(s,&w);timeval tv{(long)(timeout/1000),(long)((timeout%1000)*1000)};rc=select(0,nullptr,&w,nullptr,&tv);int err=0;int len=sizeof err;if(rc>0)getsockopt(s,SOL_SOCKET,SO_ERROR,(char*)&err,&len);if(rc<=0||err){closesocket(s);s=INVALID_SOCKET;continue;}}else if(rc==SOCKET_ERROR){closesocket(s);s=INVALID_SOCKET;continue;}nb=0;ioctlsocket(s,FIONBIO,&nb);DWORD ms=timeout;setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,(char*)&ms,sizeof ms);setsockopt(s,SOL_SOCKET,SO_SNDTIMEO,(char*)&ms,sizeof ms);break;}freeaddrinfo(res);return s;}
ProxyResult ProxyPreflight::tcp_connect(const std::string&h,unsigned p,unsigned ms)const{WsaGuard w;LARGE_INTEGER a{},b{},f{};QueryPerformanceFrequency(&f);QueryPerformanceCounter(&a);SOCKET s=connect_tcp(h,p,ms);if(s==INVALID_SOCKET)return{false,0,"tcp connect failed",{},false};closesocket(s);QueryPerformanceCounter(&b);return{true,1000.0*(b.QuadPart-a.QuadPart)/f.QuadPart,"proxy TCP endpoint reachable",{},false};}
ProxyResult ProxyPreflight::http_connect(const std::string&h,unsigned p,const std::string&t,unsigned tp,unsigned ms)const{WsaGuard w;LARGE_INTEGER a{},b{},f{};QueryPerformanceFrequency(&f);QueryPerformanceCounter(&a);SOCKET s=connect_tcp(h,p,ms);if(s==INVALID_SOCKET)return{false,0,"tcp connect failed"};auto q="CONNECT "+t+":"+std::to_string(tp)+" HTTP/1.1\r\nHost: "+t+":"+std::to_string(tp)+"\r\n\r\n";if(!send_all(s,q.data(),(int)q.size())){closesocket(s);return{false,0,"partial HTTP CONNECT request"};}std::string r;char c;while(r.size()<16384&&r.find("\r\n\r\n")==std::string::npos){if(!_recv_exact(s,&c,1)){closesocket(s);return{false,0,"partial HTTP CONNECT response"};}r+=c;}closesocket(s);QueryPerformanceCounter(&b);const auto eol=r.find("\r\n");const auto first_space=r.find(' ');const bool complete=eol!=std::string::npos&&first_space!=std::string::npos&&first_space<eol&&first_space+4<=eol&&r.compare(0,5,"HTTP/")==0;const bool accepted=complete&&r.compare(first_space+1,3,"200")==0&&(first_space+4==eol||r[first_space+4]==' ');return{accepted,1000.0*(b.QuadPart-a.QuadPart)/f.QuadPart,r,{},false};}
ProxyResult ProxyPreflight::socks5(const std::string&h,unsigned p,const std::string&t,unsigned tp,unsigned ms)const{WsaGuard w;LARGE_INTEGER a{},b{},f{};QueryPerformanceFrequency(&f);QueryPerformanceCounter(&a);SOCKET s=connect_tcp(h,p,ms);if(s==INVALID_SOCKET)return{false,0,"tcp connect failed"};char hello[3]={5,1,0},resp[4]{};if(!send_all(s,hello,3)){closesocket(s);return{false,0,"partial SOCKS5 greeting"};}if(!_recv_exact(s,resp,2)||resp[0]!=5||resp[1]!=0){closesocket(s);return{false,0,"SOCKS5 greeting failed"};}if(t.empty()||t.size()>255||tp==0||tp>65535){closesocket(s);return{false,0,"invalid target"};}std::vector<char>q={5,1,0,3,(char)t.size()};q.insert(q.end(),t.begin(),t.end());q.push_back((char)(tp>>8));q.push_back((char)tp);if(!send_all(s,q.data(),(int)q.size())){closesocket(s);return{false,0,"partial SOCKS5 CONNECT request"};}if(!_recv_exact(s,resp,4)||resp[0]!=5||resp[1]!=0||resp[2]!=0){closesocket(s);return{false,0,"SOCKS5 CONNECT failed"};}int n=resp[3]==1?4:resp[3]==4?16:resp[3]==3?1:0;if(!n){closesocket(s);return{false,0,"bad address type"};}char z;if(n==1){if(!_recv_exact(s,&z,1)){closesocket(s);return{false,0,"partial SOCKS5 reply"};}n=(unsigned char)z;if(n==0){closesocket(s);return{false,0,"empty SOCKS5 domain"};}}std::vector<char>tail((size_t)n+2);if(!_recv_exact(s,tail.data(),(int)tail.size())){closesocket(s);return{false,0,"partial SOCKS5 reply"};}closesocket(s);QueryPerformanceCounter(&b);return{true,1000.0*(b.QuadPart-a.QuadPart)/f.QuadPart,"SOCKS5 connected",{},false};}
}
